      `UPDATE customers.erasure_requests SET status='pending',available_at=now(),last_error=NULL,
       locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,updated_at=now()
       WHERE id=$1 RETURNING ${REQUEST_COLUMNS}`,
