import { pool, transaction } from '../../../packages/database/src/pool.js';
import { customerIsErased, lockCustomerPrivacy } from '../../../packages/privacy/src/tombstone.js';

export interface ProviderPaymentInput {
  paymentId: string;
  merchantId: string;
  amount: number;
  currency: string;
  paymentMethodId: string;
  providerCustomerId: string;
  customer: { id: string; email: string; name: string; externalReference: string };
  outcome: 'succeeded' | 'declined' | 'timeout';
  deliveryMode: 'standard' | 'duplicate' | 'stale_processing';
  webhookUrl: string;
}

export interface ProviderRefundInput {
  refundId: string;
  merchantId: string;
  amount: number;
  currency: string;
  reason: string;
  webhookUrl: string;
}

export interface PaymentCallback {
  id: string;
  payment_id: string;
  merchant_id: string;
  provider_customer_id: string | null;
  amount: string;
  currency: string;
  webhook_url: string;
  webhook_attempts: number;
  event_type: 'payment.succeeded' | 'payment.failed';
  delivery_mode: 'standard' | 'duplicate' | 'stale_processing';
  failure_code: string | null;
}

export interface RefundCallback {
  id: string;
  provider_payment_id: string;
  refund_id: string;
  payment_id: string;
  merchant_id: string;
  amount: string;
  currency: string;
  reason: string;
  webhook_url: string;
  webhook_attempts: number;
}

export interface SettlementPayment {
  provider_payment_id: string;
  payment_id: string;
  merchant_id: string;
  amount: string;
  currency: string;
}

export class ProviderSandboxRepository {
  async createPayment(id: string, input: ProviderPaymentInput, delayMs: number): Promise<void> {
    await transaction(async (client) => {
      await lockCustomerPrivacy(client, input.merchantId, input.customer.id);
      const erased = await customerIsErased(client, input.merchantId, input.customer.id);
      if (!erased) await client.query(
        `INSERT INTO provider_sandbox.customers(id,merchant_id,payflow_customer_id,email,name,external_reference)
         VALUES($1,$2,$3,$4,$5,$6)
         ON CONFLICT(id) DO UPDATE SET merchant_id=EXCLUDED.merchant_id,payflow_customer_id=EXCLUDED.payflow_customer_id,
           email=EXCLUDED.email,name=EXCLUDED.name,external_reference=EXCLUDED.external_reference,updated_at=now()`,
        [input.providerCustomerId, input.merchantId, input.customer.id, input.customer.email, input.customer.name, input.customer.externalReference],
      );
      await client.query(
      `INSERT INTO provider_sandbox.payment_intents
       (id,payment_id,merchant_id,amount,currency,payment_method_id,provider_customer_id,webhook_url,status,outcome,delivery_mode,failure_code,available_at,next_delivery_at)
       VALUES($1,$2,$3,$4,$5,$6,$7,$8,'processing',$9,$10,$11,now()+($12 || ' milliseconds')::interval,
              now()+($12 || ' milliseconds')::interval)`,
        [id, input.paymentId, input.merchantId, input.amount, input.currency,
          erased ? null : input.paymentMethodId, erased ? null : input.providerCustomerId, input.webhookUrl,
          input.outcome, input.deliveryMode, input.outcome === 'declined' ? 'card_declined' : null, delayMs],
      );
    });
  }

  async paymentIsRefundable(providerPaymentId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM provider_sandbox.payment_intents WHERE id=$1 AND status='succeeded'`,
      [providerPaymentId],
    );
    return Boolean(result.rowCount);
  }

  async createRefund(id: string, providerPaymentId: string, input: ProviderRefundInput, delayMs: number): Promise<void> {
    await transaction(async (client) => {
      const identity = await client.query<{ customer_id: string | null }>(
        `SELECT customer_id FROM payments.payment_intents WHERE merchant_id=$1 AND id=$2`,
        [input.merchantId, input.paymentId],
      );
      if (identity.rows[0]?.customer_id) {
        await lockCustomerPrivacy(client, input.merchantId, identity.rows[0].customer_id);
      }
      const payment = await client.query<{ retained_subject_id: string | null }>(
        `SELECT retained_subject_id FROM payments.payment_intents
         WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
        [input.merchantId, input.paymentId],
      );
      await client.query(
        `INSERT INTO provider_sandbox.refunds
         (id,provider_payment_id,refund_id,merchant_id,amount,currency,reason,webhook_url,status,available_at,next_delivery_at)
         VALUES($1,$2,$3,$4,$5,$6,$7,$8,'pending',now()+($9 || ' milliseconds')::interval,
                now()+($9 || ' milliseconds')::interval)`,
        [id, providerPaymentId, input.refundId, input.merchantId, input.amount, input.currency,
          payment.rows[0]?.retained_subject_id ? '[redacted]' : input.reason, input.webhookUrl, delayMs],
      );
    });
  }

  async claimPaymentCallback(): Promise<PaymentCallback | undefined> {
